-- 通用查询一期，幂等导入元数据和初始配置，不修改业务数据。
SET NAMES utf8mb4;
SET SESSION group_concat_max_len=1048576;
CREATE TABLE IF NOT EXISTS sys_metadata_table (table_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,schema_name VARCHAR(64) NOT NULL,table_name VARCHAR(64) NOT NULL,table_comment VARCHAR(500) NOT NULL DEFAULT '',display_name VARCHAR(100) NOT NULL,structure_signature VARCHAR(64) NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,synchronized_time DATETIME NOT NULL,version INT NOT NULL DEFAULT 0,UNIQUE KEY uk_metadata_table(schema_name,table_name),create_by VARCHAR(64) NOT NULL,create_time DATETIME NOT NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sys_metadata_column (column_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,table_id BIGINT NOT NULL,column_name VARCHAR(64) NOT NULL,column_comment VARCHAR(1000) NOT NULL DEFAULT '',display_name VARCHAR(100) NOT NULL,data_type VARCHAR(16) NOT NULL,column_type VARCHAR(100) NOT NULL,max_length BIGINT NULL,numeric_scale INT NULL,nullable BOOLEAN NOT NULL,primary_key BOOLEAN NOT NULL,ordinal_position INT NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uk_metadata_column(table_id,column_name),create_by VARCHAR(64) NOT NULL,create_time DATETIME NOT NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sys_query_definition (definition_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,query_key VARCHAR(64) NOT NULL,display_name VARCHAR(100) NOT NULL,adapter_key VARCHAR(64) NOT NULL,draft_version INT NOT NULL DEFAULT 0,published_revision INT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uk_query_key(query_key),create_by VARCHAR(64) NOT NULL,create_time DATETIME NOT NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sys_query_field (field_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,definition_id BIGINT NOT NULL,field_key VARCHAR(64) NOT NULL,source_key VARCHAR(32) NOT NULL,column_id BIGINT NOT NULL,label VARCHAR(100) NOT NULL,component VARCHAR(16) NOT NULL,operators_json JSON NOT NULL,default_operator VARCHAR(24) NOT NULL,option_provider VARCHAR(32) NOT NULL DEFAULT '',common_visible BOOLEAN NOT NULL DEFAULT FALSE,display_order INT NOT NULL,sortable BOOLEAN NOT NULL DEFAULT FALSE,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uk_query_field(definition_id,field_key),KEY idx_query_column(column_id),create_by VARCHAR(64) NOT NULL,create_time DATETIME NOT NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sys_query_release (release_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,definition_id BIGINT NOT NULL,revision INT NOT NULL,config_snapshot JSON NOT NULL,structure_signature TEXT NOT NULL,UNIQUE KEY uk_query_release(definition_id,revision),create_by VARCHAR(64) NOT NULL,create_time DATETIME NOT NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
START TRANSACTION;
SET @query_now=UTC_TIMESTAMP()+INTERVAL 8 HOUR;
SELECT DATABASE(),t.TABLE_NAME,t.TABLE_COMMENT,COALESCE(NULLIF(t.TABLE_COMMENT,''),t.TABLE_NAME),(SELECT SHA2(GROUP_CONCAT(CONCAT(c.COLUMN_NAME,'|',c.COLUMN_TYPE,'|',IF(c.IS_NULLABLE='YES','true','false'),'|',c.COLUMN_COMMENT,'|',c.ORDINAL_POSITION,';') ORDER BY c.ORDINAL_POSITION SEPARATOR ''),256) FROM information_schema.COLUMNS c WHERE c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=t.TABLE_NAME),TRUE,@query_now,0,'admin',@query_now,'admin',@query_now FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME IN ('md_item','purchase_order','purchase_order_line') AND NOT EXISTS(SELECT 1 FROM sys_metadata_table m WHERE m.schema_name=DATABASE() AND m.table_name=t.TABLE_NAME);
SELECT t.table_id,c.COLUMN_NAME,c.COLUMN_COMMENT,LEFT(COALESCE(NULLIF(c.COLUMN_COMMENT,''),c.COLUMN_NAME),100),CASE WHEN c.DATA_TYPE IN ('varchar','char','text') THEN 'STRING' WHEN c.DATA_TYPE='tinyint' AND c.COLUMN_TYPE='tinyint(1)' THEN 'BOOLEAN' WHEN c.DATA_TYPE IN ('tinyint','int','bigint','smallint','mediumint') THEN 'INTEGER' WHEN c.DATA_TYPE='decimal' THEN 'DECIMAL' WHEN c.DATA_TYPE='date' THEN 'DATE' WHEN c.DATA_TYPE IN ('datetime','timestamp') THEN 'DATETIME' ELSE 'UNSUPPORTED' END,c.COLUMN_TYPE,c.CHARACTER_MAXIMUM_LENGTH,c.NUMERIC_SCALE,c.IS_NULLABLE='YES',c.COLUMN_KEY='PRI',c.ORDINAL_POSITION,TRUE,'admin',@query_now,'admin',@query_now FROM sys_metadata_table t JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=t.schema_name AND c.TABLE_NAME=t.table_name WHERE t.table_name IN ('md_item','purchase_order','purchase_order_line') AND NOT EXISTS(SELECT 1 FROM sys_metadata_column m WHERE m.table_id=t.table_id AND m.column_name=c.COLUMN_NAME);
SELECT d.definition_id,1,JSON_OBJECT('queryKey',d.query_key,'displayName',d.display_name,'configVersion',1,'enabled',JSON_EXTRACT('true','$'),'relations',JSON_OBJECT(),'fields',(SELECT JSON_ARRAYAGG(JSON_OBJECT('fieldKey',f.field_key,'sourceKey',f.source_key,'columnId',f.column_id,'columnName',c.column_name,'columnType',c.column_type,'dataType',c.data_type,'maxLength',c.max_length,'numericScale',c.numeric_scale,'nullable',JSON_EXTRACT(IF(c.nullable,'true','false'),'$'),'label',f.label,'component',f.component,'operators',f.operators_json,'defaultOperator',f.default_operator,'optionProvider',f.option_provider,'commonVisible',JSON_EXTRACT(IF(f.common_visible,'true','false'),'$'),'displayOrder',f.display_order,'sortable',JSON_EXTRACT(IF(f.sortable,'true','false'),'$'))) FROM sys_query_field f JOIN sys_metadata_column c ON c.column_id=f.column_id WHERE f.definition_id=d.definition_id AND f.enabled=TRUE)), (SELECT SHA2(GROUP_CONCAT(CONCAT(f.column_id,':',c.column_type) ORDER BY f.field_key SEPARATOR ';'),256) FROM sys_query_field f JOIN sys_metadata_column c ON c.column_id=f.column_id WHERE f.definition_id=d.definition_id AND f.enabled=TRUE), 'admin',@query_now,'admin',@query_now FROM sys_query_definition d WHERE d.query_key='masterdata.item' AND d.published_revision=0 AND NOT EXISTS(SELECT 1 FROM sys_query_release r WHERE r.definition_id=d.definition_id);
UPDATE sys_query_definition d SET published_revision=1 WHERE d.query_key='masterdata.item' AND d.published_revision=0 AND EXISTS(SELECT 1 FROM sys_query_release r WHERE r.definition_id=d.definition_id AND r.revision=1);
SELECT d.definition_id,1,JSON_OBJECT('queryKey',d.query_key,'displayName',d.display_name,'configVersion',1,'enabled',JSON_EXTRACT('true','$'),'relations',JSON_OBJECT('lines','订单明细'),'fields',(SELECT JSON_ARRAYAGG(JSON_OBJECT('fieldKey',f.field_key,'sourceKey',f.source_key,'columnId',f.column_id,'columnName',c.column_name,'columnType',c.column_type,'dataType',c.data_type,'maxLength',c.max_length,'numericScale',c.numeric_scale,'nullable',JSON_EXTRACT(IF(c.nullable,'true','false'),'$'),'label',f.label,'component',f.component,'operators',f.operators_json,'defaultOperator',f.default_operator,'optionProvider',f.option_provider,'commonVisible',JSON_EXTRACT(IF(f.common_visible,'true','false'),'$'),'displayOrder',f.display_order,'sortable',JSON_EXTRACT(IF(f.sortable,'true','false'),'$'))) FROM sys_query_field f JOIN sys_metadata_column c ON c.column_id=f.column_id WHERE f.definition_id=d.definition_id AND f.enabled=TRUE)), (SELECT SHA2(GROUP_CONCAT(CONCAT(f.column_id,':',c.column_type) ORDER BY f.field_key SEPARATOR ';'),256) FROM sys_query_field f JOIN sys_metadata_column c ON c.column_id=f.column_id WHERE f.definition_id=d.definition_id AND f.enabled=TRUE), 'admin',@query_now,'admin',@query_now FROM sys_query_definition d WHERE d.query_key='purchase.order' AND d.published_revision=0 AND NOT EXISTS(SELECT 1 FROM sys_query_release r WHERE r.definition_id=d.definition_id);
UPDATE sys_query_definition d SET published_revision=1 WHERE d.query_key='purchase.order' AND d.published_revision=0 AND EXISTS(SELECT 1 FROM sys_query_release r WHERE r.definition_id=d.definition_id AND r.revision=1);
-- 为缺少数据库注释的初始业务字段补充默认中文标签，不覆盖人工维护名称。
UPDATE sys_metadata_column c JOIN sys_metadata_table t ON t.table_id=c.table_id JOIN sys_query_field f ON f.column_id=c.column_id SET c.display_name=f.label WHERE c.display_name=c.column_name AND c.column_comment='' AND t.version=0 AND c.create_time=@query_now;
UPDATE sys_metadata_table t SET t.structure_signature=(SELECT SHA2(GROUP_CONCAT(CONCAT(c.COLUMN_NAME,'|',c.COLUMN_TYPE,'|',IF(c.IS_NULLABLE='YES','true','false'),'|',c.COLUMN_COMMENT,'|',c.ORDINAL_POSITION,';') ORDER BY c.ORDINAL_POSITION SEPARATOR ''),256) FROM information_schema.COLUMNS c WHERE c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=t.TABLE_NAME) WHERE t.schema_name=DATABASE() AND t.structure_signature='';
SET @tools_parent=(SELECT menu_id FROM sys_menu WHERE path='tool' AND menu_type='M' ORDER BY menu_id LIMIT 1);
UPDATE sys_menu SET status='0',update_by='admin',update_time=@query_now WHERE menu_id=@tools_parent AND status='1';
SET @query_parent=(SELECT menu_id FROM sys_menu WHERE path='query' AND menu_type IN ('M','C') AND menu_name='查询管理' ORDER BY menu_id LIMIT 1);
UPDATE sys_menu SET menu_name='导入业务表' WHERE menu_name='数据目录import' AND perms LIKE 'query:%';
UPDATE sys_menu SET menu_name='修改目录名称' WHERE menu_name='数据目录edit' AND perms LIKE 'query:%';
UPDATE sys_menu SET menu_name='同步数据目录' WHERE menu_name='数据目录sync' AND perms LIKE 'query:%';
UPDATE sys_menu SET menu_name='编辑查询草稿' WHERE menu_name='查询配置edit' AND perms LIKE 'query:%';
UPDATE sys_menu SET menu_name='预览查询草稿' WHERE menu_name='查询配置preview' AND perms LIKE 'query:%';
UPDATE sys_menu SET menu_name='发布查询配置' WHERE menu_name='查询配置publish' AND perms LIKE 'query:%';
COMMIT;
